package org.example.controller;

import javafx.fxml.FXML;import javafx.scene.control.*;import javafx.stage.Stage;
import org.example.api.admin.AdminApiClient;import org.example.service.NotificationService;import org.example.util.IconFactory;
import java.util.regex.Pattern;

/** Shared premium Add/Edit User form backed by the Spring admin API. */
public class UserDialogController {
 private static final Pattern EMAIL=Pattern.compile("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+$");
 @FXML private Label lblTitle,lblSubtitle,lblMessage;@FXML private TextField txtFullName,txtUsername,txtEmail,txtDepartment,txtBranch;@FXML private PasswordField txtPassword,txtConfirm;@FXML private ComboBox<String> cmbRole,cmbAccess;@FXML private CheckBox chkActive,chkLocked,chkMfa;@FXML private Button btnSave,btnCancel;
 private Integer editingUserId;private String originalUsername;private final AdminApiClient api=new AdminApiClient();
 @FXML public void initialize(){loadRoles();cmbAccess.getItems().setAll("FULL ACCESS","STANDARD","LIMITED ACCESS","READ ONLY");cmbAccess.setValue("STANDARD");chkActive.setSelected(true);btnSave.setGraphic(IconFactory.icon("save",16));btnCancel.setGraphic(IconFactory.icon("cancel",16));installLiveValidation();}
 public void editUser(int userId){editingUserId=userId;lblTitle.setText("Edit User Account");lblSubtitle.setText("Update identity, role, access and account security");btnSave.setText("Update User");txtPassword.setPromptText("Leave blank to keep current password");txtConfirm.setPromptText("Confirm new password");try{var u=api.user(userId);originalUsername=u.username();txtFullName.setText(nvl(u.fullName()));txtUsername.setText(nvl(u.username()));txtEmail.setText(nvl(u.email()));txtDepartment.setText(nvl(u.department()));txtBranch.setText(nvl(u.branch()));cmbRole.setValue(nvl(u.role()));cmbAccess.setValue(blank(u.accessLevel(),"STANDARD"));chkActive.setSelected(u.active());chkLocked.setSelected(u.locked());chkMfa.setSelected(u.mfaEnabled());}catch(Exception e){message("Unable to load user: "+e.getMessage(),true);}}
 private void loadRoles(){cmbRole.getItems().clear();try{cmbRole.getItems().setAll(api.roles().stream().filter(AdminApiClient.RoleDto::active).map(AdminApiClient.RoleDto::name).toList());}catch(Exception e){message("Unable to load roles: "+e.getMessage(),true);}if(cmbRole.getItems().contains("SALES"))cmbRole.setValue("SALES");else if(!cmbRole.getItems().isEmpty())cmbRole.getSelectionModel().selectFirst();}
 @FXML private void save(){clearInvalid();if(!validateForm())return;try{api.saveUser(new AdminApiClient.UserSaveRequest(editingUserId,txtUsername.getText().trim(),blank(txtPassword.getText())?null:txtPassword.getText(),txtFullName.getText().trim(),txtEmail.getText().trim(),cmbRole.getValue(),txtDepartment.getText().trim(),cmbAccess.getValue(),txtBranch.getText().trim(),chkActive.isSelected(),chkLocked.isSelected(),chkMfa.isSelected()));NotificationService.add(editingUserId==null?"User "+txtUsername.getText().trim()+" created with "+cmbRole.getValue()+" access.":"User "+originalUsername+" updated.");close();}catch(Exception e){String m=e.getMessage()==null?"":e.getMessage().toLowerCase();if(m.contains("unique")||m.contains("duplicate"))invalid(txtUsername,"This username already exists.");else message("Unable to save user: "+e.getMessage(),true);}}
 private boolean validateForm(){if(blank(txtFullName.getText()))return invalid(txtFullName,"Full name is required.");if(blank(txtUsername.getText()))return invalid(txtUsername,"Username is required.");if(blank(txtEmail.getText()))return invalid(txtEmail,"Email address is required.");if(!EMAIL.matcher(txtEmail.getText().trim()).matches())return invalid(txtEmail,"Enter a valid email address.");if(cmbRole.getValue()==null)return invalid(cmbRole,"Select a role.");if(cmbAccess.getValue()==null)return invalid(cmbAccess,"Select an access level.");boolean passwordRequired=editingUserId==null;if(passwordRequired&&blank(txtPassword.getText()))return invalid(txtPassword,"Password is required.");if(!blank(txtPassword.getText())&&txtPassword.getText().length()<6)return invalid(txtPassword,"Password must contain at least 6 characters.");if(!txtPassword.getText().equals(txtConfirm.getText()))return invalid(txtConfirm,"Passwords do not match.");return true;}
 private void installLiveValidation(){txtFullName.textProperty().addListener((o,a,b)->clearInvalid(txtFullName));txtUsername.textProperty().addListener((o,a,b)->clearInvalid(txtUsername));txtEmail.textProperty().addListener((o,a,b)->clearInvalid(txtEmail));txtPassword.textProperty().addListener((o,a,b)->clearInvalid(txtPassword));txtConfirm.textProperty().addListener((o,a,b)->clearInvalid(txtConfirm));cmbRole.valueProperty().addListener((o,a,b)->clearInvalid(cmbRole));cmbAccess.valueProperty().addListener((o,a,b)->clearInvalid(cmbAccess));}
 private boolean invalid(Control c,String text){c.getStyleClass().add("validation-error");c.requestFocus();message(text,true);return false;}private void clearInvalid(){for(Control c:new Control[]{txtFullName,txtUsername,txtEmail,txtPassword,txtConfirm,cmbRole,cmbAccess})clearInvalid(c);lblMessage.setText("");}private void clearInvalid(Control c){c.getStyleClass().remove("validation-error");}@FXML private void cancel(){close();}private void close(){((Stage)txtUsername.getScene().getWindow()).close();}private void message(String text,boolean error){lblMessage.setText(text);lblMessage.getStyleClass().setAll(error?"dialog-error":"dialog-success");}private static boolean blank(String v){return v==null||v.isBlank();}private static String nvl(String v){return v==null?"":v;}private static String blank(String v,String f){return blank(v)?f:v;}
}
